class Solution { public: vector<int> assignTasks(vector<int>& servers,vector<int>& tasks){using Free=pair<int,int>;using Busy=tuple<long long,int,int>;priority_queue<Free,vector<Free>,greater<Free>> available;priority_queue<Busy,vector<Busy>,greater<Busy>> busy;for(int i=0;i<(int)servers.size();++i)available.push({servers[i],i});vector<int> answer(tasks.size());long long time=0;for(int i=0;i<(int)tasks.size();++i){time=max(time,(long long)i);if(available.empty())time=max(time,get<0>(busy.top()));while(!busy.empty()&&get<0>(busy.top())<=time){auto [finish,weight,index]=busy.top();busy.pop();available.push({weight,index});}auto [weight,index]=available.top();available.pop();answer[i]=index;busy.push({time+tasks[i],weight,index});}return answer;} };
